                else if (m >= 7000000000 && m <= 11000000000) marketComp = 0.55;
                else marketComp = 0.25;                                         // inflated / implausible
                score = 100 * (0.55 * credComp + 0.30 * biasComp + 0.15 * marketComp);
            } else {
                score = 100 * (0.65 * credComp + 0.35 * biasComp);
            }
            return Math.round(Math.max(0, Math.min(100, score)));
        }

        _letterGrade(s) {
            return s >= 85 ? `A` : s >= 70 ? `B` : s >= 55 ? `C` : s >= 40 ? `D` : `F`;
        }

        _perfTier(credibility, bias) {
            if (credibility >= 120 && bias <= 25) return `excelente`;
            if (credibility >= 90 && bias <= 40) return `solido`;
            if (credibility >= 65) return `aceptable`;
            return `principiante`;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var cp = state.currentPeriod;
            var credibilityDelta = 0;
            var biasDelta = 0;
            var marketEst = ds.marketEstimate;
            var costRound = 0;
            var notes = ``;

            if (cp === 1) {
                var costPerOnline = 40000;
                var costPerInPerson = 120000;
                var onlineFrac = d.onlinePct / 100;
                var perInterviewCost = onlineFrac * costPerOnline + (1 - onlineFrac) * costPerInPerson;
                costRound = Math.round(perInterviewCost * d.sampleSize);

                var sampleSizeScore = 0;
                if (d.sampleSize >= 1050) sampleSizeScore = 10;
                else if (d.sampleSize >= 600) sampleSizeScore = 4;

                var onlineBias = 0;
                if (d.onlinePct >= 70) onlineBias = 22;
                else if (d.onlinePct >= 50) onlineBias = 12;
                else if (d.onlinePct >= 30) onlineBias = 6;
                else onlineBias = 3;

                var questionBias = 0;
                if (d.neutralQ === `leading`) questionBias = 18;
                else if (d.neutralQ === `mixed`) questionBias = 8;
                else questionBias = 2;

                biasDelta = onlineBias + questionBias;
                credibilityDelta = sampleSizeScore - (onlineBias / 2) - (questionBias / 2);
                notes = `Sesgo de muestreo: ` + onlineBias + ` pts. Sesgo de pregunta: ` + questionBias + ` pts.`;
            } else if (cp === 2) {
                var weightingGain = 0;
                if (d.weightIncome >= 20 && d.weightIncome <= 30) weightingGain = 14;
                else if (d.weightIncome >= 10) weightingGain = 8;
                else if (d.weightIncome > 0) weightingGain = 3;
                else weightingGain = -6;

                var nrGain = 0;
                if (d.nonResponseAdj === `followup`) nrGain = 12;
                else if (d.nonResponseAdj === `reweight`) nrGain = 6;
                else nrGain = -5;

                var gapGain = 0;
                if (d.intentionDiscount >= 25 && d.intentionDiscount <= 45) gapGain = 16;
                else if (d.intentionDiscount >= 15) gapGain = 8;
                else if (d.intentionDiscount > 0) gapGain = 3;
                else gapGain = -8;

                credibilityDelta = weightingGain + nrGain + gapGain;
                biasDelta = -(weightingGain + nrGain + gapGain) / 2;
                notes = `Corrección por ponderación: ` + weightingGain + ` pts. Corrección no-respuesta: ` + nrGain + ` pts. Brecha intención: ` + gapGain + ` pts.`;
            } else if (cp === 3) {
                if (d.method === `A`) { marketEst = 11000000000; credibilityDelta = -4; }
                else if (d.method === `B`) { marketEst = 8500000000; credibilityDelta = 10; }
                else { marketEst = 11900000000; credibilityDelta = 2; }

                var growthPenalty = 0;
                if (d.growthAssumption >= 12 && d.growthAssumption <= 20) growthPenalty = 6;
                else if (d.growthAssumption > 25) growthPenalty = -10;
                else if (d.growthAssumption < 8) growthPenalty = -4;

                var capturePenalty = 0;
                if (d.abastiaCapture >= 15 && d.abastiaCapture <= 30) capturePenalty = 6;
                else if (d.abastiaCapture > 45) capturePenalty = -10;
                else capturePenalty = -2;

                credibilityDelta += growthPenalty + capturePenalty;
                biasDelta = (d.method === `A` ? 10 : (d.method === `C` ? 12 : -4));
                notes = `Método ` + d.method + `. Crecimiento ` + d.growthAssumption + `%. Captura ` + d.abastiaCapture + `%.`;
            } else if (cp === 4) {
                var recScore = 0;
                if (d.recommend === `invest_partial`) recScore = 14;
                else if (d.recommend === `defer`) recScore = 8;
                else if (d.recommend === `invest_full`) recScore = -6;
                else recScore = -2;

                var confScore = 0;
                if (d.confidence === `balanced`) confScore = 10;
                else if (d.confidence === `cautious`) confScore = 6;
                else confScore = -10;

                var discScore = 0;
                if (d.disclosure === `full`) discScore = 12;
                else if (d.disclosure === `partial`) discScore = 4;
                else discScore = -14;

                credibilityDelta = recScore + confScore + discScore;
                biasDelta = -(confScore + discScore) / 2;
                notes = `Recomendación: ` + d.recommend + `. Confianza: ` + d.confidence + `. Divulgación: ` + d.disclosure + `.`;
            }

            ds.credibility = Math.max(0, Math.min(150, ds.credibility + credibilityDelta));
            ds.biasIndex = Math.max(0, Math.min(100, ds.biasIndex + biasDelta));
            ds.marketEstimate = marketEst;
            ds.budgetUsed += costRound;

            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.biasHistory.push(Math.round(ds.biasIndex));
            ds.marketHistory.push(marketEst);

            // ── Scoring for the platform reporting/grading layer ──────────────
            // express_extractMetrics() reads domainState.performance.overallScore /
            // .grade for the instructor Score column and the LTI grade passback;
            // express_extractHistory() reads the same path inside each history
            // snapshot for the per-round progression. Writing it here (before the
            // engine snapshots domainState into history and persists PERIOD_END)
            // populates every read path. Mirrored into results.* as a belt-and-braces
            // fallback (extractHistory routes 3-6).
            var overallScore = this._computeScore(ds);
            var grade = this._letterGrade(overallScore);
            ds.performance = { overallScore: overallScore, grade: grade };

            var results = {
                period: cp,
                credibilityDelta: Math.round(credibilityDelta * 10) / 10,
                biasDelta: Math.round(biasDelta * 10) / 10,
                credibility: Math.round(ds.credibility),
                biasIndex: Math.round(ds.biasIndex),
                marketEstimate: marketEst,
                costRound: costRound,
                overallScore: overallScore,
                score: overallScore,
                grade: grade,
                notes: notes
            };

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
