        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var final = last.results || {};
            var ds = last.domainState || {};
            var credibility = final.credibility != null ? final.credibility : (ds.credibility || 0);
            var bias = final.biasIndex != null ? final.biasIndex : (ds.biasIndex || 0);
            var market = final.marketEstimate != null ? final.marketEstimate : (ds.marketEstimate || 0);

            var overallScore = (ds.performance && ds.performance.overallScore != null)
                ? ds.performance.overallScore
                : (final.overallScore != null ? final.overallScore : this._computeScore({ credibility: credibility, biasIndex: bias, marketEstimate: market }));
            var grade = (ds.performance && ds.performance.grade) ? ds.performance.grade : this._letterGrade(overallScore);
            var tier = this._perfTier(credibility, bias);

            var insights = [];
            if (credibility >= 120) insights.push(window.mySimulation.t(`insight_strong`));
            if (bias > 40) insights.push(window.mySimulation.t(`insight_bias`));
            if (market >= 8000000000 && market <= 9500000000) insights.push(window.mySimulation.t(`insight_market_ok`));
            if (market >= 11500000000) insights.push(window.mySimulation.t(`insight_market_high`));
            if (!insights.length) insights.push(window.mySimulation.t(`insight_default`));

            return {
                overallScore: overallScore,
                grade: grade,
                credibility: credibility,
                biasIndex: bias,
                marketEstimate: market,
                performanceTier: tier,
                performance: window.mySimulation.t(`perf_` + tier),
                insights: insights,
                totalPeriods: history.length
            };
        }

        // Rendered by the production engine's showCompletion() (which calls
        // formatCompletionMessage). Without this the base default only prints
        // "You completed N periods" and discards the entire debrief, so the
        // student never sees their score or feedback. Fully localised.
        formatCompletionMessage(summary) {
            var t = (k) => window.mySimulation.t(k);
            summary = summary || {};
            var market = summary.marketEstimate || 0;
            var marketStr = market > 0 ? (`COP ` + (market / 1000000000).toFixed(1) + `B`) : `—`;
            var insights = Array.isArray(summary.insights) ? summary.insights : [];

            var rows = ``;
            var row = function(label, val) {
                return `<div style="display:flex;justify-content:space-between;gap:16px;padding:6px 0;border-bottom:1px solid #eee;">` +
                    `<span style="color:#6b5a3e;">` + label + `</span>` +
                    `<span style="font-weight:700;color:#2a1f14;">` + val + `</span></div>`;
            };
            rows += row(t(`score_label`), (summary.overallScore != null ? summary.overallScore : 0) + ` / 100 (` + (summary.grade || `—`) + `)`);
            rows += row(t(`credibility_label`), Math.round(summary.credibility || 0) + ` / 150`);
            rows += row(t(`bias_label`), Math.round(summary.biasIndex || 0) + ` / 100`);
            rows += row(t(`market_label`), marketStr);
            rows += row(t(`perf_label`), summary.performance || t(`perf_` + (summary.performanceTier || `principiante`)));

            var insightHtml = ``;
            if (insights.length) {
                insightHtml = `<div style="margin-top:14px;text-align:left;">` +
                    `<div style="font-weight:700;color:#003893;margin-bottom:6px;">` + t(`insights_label`) + `</div>` +
                    `<ul style="margin:0;padding-left:20px;color:#2a1f14;">` +
                    insights.map(function(i) { return `<li style="margin-bottom:4px;">` + i + `</li>`; }).join(``) +
                    `</ul></div>`;
            }

            return `<div class="qr-completion" style="padding:8px 4px;">` +
                `<p style="font-size:1.05rem;font-weight:700;color:#003893;margin-bottom:12px;">` + t(`completion_headline`) + `</p>` +
                `<div style="max-width:460px;margin:0 auto;">` + rows + `</div>` +
                insightHtml +
                `</div>`;
        }

